sys_script.script:
(function executeRule(current, previous) {
    var sysId = current.getUniqueValue();

    // Check child areas
    var childGr = new GlideRecord('x_1966159_utilit_0_area');
    childGr.addQuery('parent', sysId);
    childGr.setLimit(1);
    childGr.query();
    if (childGr.hasNext()) {
        gs.addErrorMessage('Cannot delete this area. It has child areas referencing it.');
        current.setAbortAction(true);
        return;
    }

    // Check substations
    var subGr = new GlideRecord('x_1966159_utilit_0_substation');
    if (subGr.isValid()) {
        subGr.addQuery('area', sysId);
        subGr.setLimit(1);
        subGr.query();
        if (subGr.hasNext()) {
            gs.addErrorMessage('Cannot delete this area. It is referenced by substations.');
            current.setAbortAction(true);
            return;
        }
    }

    // Check transformers
    var txGr = new GlideRecord('x_1966159_utilit_0_transformer');
    if (txGr.isValid()) {
        txGr.addQuery('area', sysId);
        txGr.setLimit(1);
        txGr.query();
        if (txGr.hasNext()) {
            gs.addErrorMessage('Cannot delete this area. It is referenced by transformers.');
            current.setAbortAction(true);
            return;
        }
    }

    // Check service connections
    var scGr = new GlideRecord('x_1966159_utilit_0_svc_conn');
    if (scGr.isValid()) {
        scGr.addQuery('area', sysId);
        scGr.setLimit(1);
        scGr.query();
        if (scGr.hasNext()) {
            gs.addErrorMessage('Cannot delete this area. It is referenced by service connections.');
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
